query:
PREFIX base: <https://baseballontology.org/>
PREFIX cco: <https://www.commoncoreontologies.org/>
PREFIX obo: <http://purl.obolibrary.org/obo/>
SELECT *
FROM NAMED <https://w3id.org/baseball/graph/game/822693>
FROM NAMED <https://w3id.org/baseball/graph/game/822773>
FROM NAMED <https://w3id.org/baseball/graph/game/823016>
FROM NAMED <https://w3id.org/baseball/graph/game/823098>
FROM NAMED <https://w3id.org/baseball/graph/game/823181>
FROM NAMED <https://w3id.org/baseball/graph/game/823259>
FROM NAMED <https://w3id.org/baseball/graph/game/823505>
FROM NAMED <https://w3id.org/baseball/graph/game/823585>
FROM NAMED <https://w3id.org/baseball/graph/game/823826>
FROM NAMED <https://w3id.org/baseball/graph/game/823989>
FROM NAMED <https://w3id.org/baseball/graph/game/824233>
FROM NAMED <https://w3id.org/baseball/graph/game/824556>
FROM NAMED <https://w3id.org/baseball/graph/game/824881>
FROM NAMED <https://w3id.org/baseball/graph/game/824962>
FROM NAMED <https://w3id.org/baseball/graph/game/825042>
WHERE {
{ {

# Existing-term evidence inventory, not a completeness certificate. Every row
# keeps its promoted graph and world-side referent. No provider event labels,
# inferred continuity, inferred causation, or missing-row negative assertions.
SELECT DISTINCT ?graph ?game ?kind ?entity ?player ?act ?roleType
                ?reviewRecord ?original ?operative ?disposition ?decision
                ?trajectory ?episode ?trajectoryHalf ?trajectoryInterval
WHERE {
  VALUES ?graph { <https://w3id.org/baseball/graph/game/822693> <https://w3id.org/baseball/graph/game/822773> <https://w3id.org/baseball/graph/game/823016> <https://w3id.org/baseball/graph/game/823098> <https://w3id.org/baseball/graph/game/823181> <https://w3id.org/baseball/graph/game/823259> <https://w3id.org/baseball/graph/game/823505> <https://w3id.org/baseball/graph/game/823585> <https://w3id.org/baseball/graph/game/823826> <https://w3id.org/baseball/graph/game/823989> <https://w3id.org/baseball/graph/game/824233> <https://w3id.org/baseball/graph/game/824556> <https://w3id.org/baseball/graph/game/824881> <https://w3id.org/baseball/graph/game/824962> <https://w3id.org/baseball/graph/game/825042> }
  GRAPH ?graph {
    ?game a base:BaseballGame .
    {
      ?entity a base:PlateAppearance ;
          obo:BFO_0000132/obo:BFO_0000132/obo:BFO_0000132 ?game .
      BIND("plate_appearance" AS ?kind)
    } UNION {
      VALUES (?entityType ?kind) {
        (base:BattedBallPlayProcess "batted_play") (base:RunProcess "run")
      }
      ?entity a ?entityType ; obo:BFO_0000132+ ?game .
    } UNION {
      ?act obo:BFO_0000132+ ?game ; obo:BFO_0000055 ?role .
      ?role obo:BFO_0000197 ?player ; a ?roleType .
      VALUES ?roleType { base:BatterRole base:BaserunnerRole base:PitcherRole base:FielderRole }
      BIND(?player AS ?entity)
      BIND("player_game" AS ?kind)
    } UNION {
      ?trajectory a obo:BFO_0000015 ; obo:BFO_0000117 ?episode ;
          obo:BFO_0000057 ?player ; obo:BFO_0000132 ?trajectoryHalf ;
          obo:BFO_0000199 ?trajectoryInterval .
      ?trajectoryHalf a base:HalfInning ; obo:BFO_0000132/obo:BFO_0000132 ?game .
      FILTER(REGEX(STR(?trajectory), "^https://baseballontology[.]org/data/game/[0-9]+/runner-trajectory/[^/]+$"))
      BIND(?trajectory AS ?entity)
      BIND("runner_history" AS ?kind)
    } UNION {
      ?entity a base:BaseballReplayReviewAct .
      ?reviewRecord a base:BaseballReplayReviewEventRecord ;
        cco:ont00001808 ?entity, ?resultJudgment .
      ?resultJudgment obo:BFO_0000132 ?result .
      ?result a base:BaseballInstitutionalProcess ; obo:BFO_0000132 ?reviewPA .
      ?reviewPA a base:PlateAppearance ;
        obo:BFO_0000132/obo:BFO_0000132/obo:BFO_0000132 ?game .
      BIND("review" AS ?kind)
      OPTIONAL {
        ?reviewRecord a base:BaseballReplayReviewEventRecord ;
          cco:ont00001808 ?entity, ?onFieldJudgment, ?original, ?operative, ?disposition .
        ?onFieldJudgment a base:ReviewedOnFieldUmpireJudgmentAct ;
          cco:ont00001986 ?original ; obo:BFO_0000063 ?entity .
        ?entity cco:ont00001921 ?original ; cco:ont00001986 ?operative .
        ?original a base:ReviewedOnFieldBaseballDecisionICE .
        ?operative a base:BaseballReplayDecisionICE .
        ?disposition a base:BaseballReplayReviewDispositionICE, ?dispositionType ;
          cco:ont00001816 ?entity ; cco:ont00001808 ?original, ?operative .
        VALUES (?dispositionType ?decision) {
          (base:AffirmingBaseballReplayReviewDispositionICE "affirmed")
          (base:OverturningBaseballReplayReviewDispositionICE "reversed")
        }
      }
    }
  }
  FILTER(STRSTARTS(STR(?graph), "https://w3id.org/baseball/graph/game/"))
}

} } UNION { {

# Read-only evidence over accepted MLB-game relations, not scored trajectories.
# Each distinct combination remains visible; no path coalescence or credit is
# inferred. Unbound values remain unknown. Codes come from explicit identifiers.
SELECT DISTINCT ?graph ?game ?plateAppearance ?resolution ?act ?runner ?episode
       ?originDesignation ?originRecord ?originBase ?originCode ?destinationBase ?destinationCode
       ?safeJudgment ?safeDecision
       ?trajectory ?trajectoryHalf ?trajectoryInterval
       ?batter ?metricOrigin ?awardRule
       ?contactPlay ?award ?record ?hasSafeType ?hasOutType ?hasRunType
WHERE {
  VALUES ?graph { <https://w3id.org/baseball/graph/game/822693> <https://w3id.org/baseball/graph/game/822773> <https://w3id.org/baseball/graph/game/823016> <https://w3id.org/baseball/graph/game/823098> <https://w3id.org/baseball/graph/game/823181> <https://w3id.org/baseball/graph/game/823259> <https://w3id.org/baseball/graph/game/823505> <https://w3id.org/baseball/graph/game/823585> <https://w3id.org/baseball/graph/game/823826> <https://w3id.org/baseball/graph/game/823989> <https://w3id.org/baseball/graph/game/824233> <https://w3id.org/baseball/graph/game/824556> <https://w3id.org/baseball/graph/game/824881> <https://w3id.org/baseball/graph/game/824962> <https://w3id.org/baseball/graph/game/825042> }
  GRAPH ?graph {
    ?game a base:BaseballGame .
    ?plateAppearance a base:PlateAppearance ;
        obo:BFO_0000132/obo:BFO_0000132/obo:BFO_0000132 ?game .
    ?resolution a base:RunnerResolutionProcess ;
        obo:BFO_0000132 ?plateAppearance ; obo:BFO_0000062 ?act .
    ?act a base:BaserunningAct ; obo:BFO_0000132 ?plateAppearance .
    OPTIONAL { ?episode a base:RunnerResolutionEpisode ; obo:BFO_0000132 ?plateAppearance ;
          obo:BFO_0000117 ?resolution, ?act .
      ?act a base:BaserunningAct ; cco:ont00001833 ?runner ; obo:BFO_0000132 ?plateAppearance .
      OPTIONAL {
        ?trajectory a obo:BFO_0000015 ; obo:BFO_0000117 ?episode ;
            obo:BFO_0000057 ?runner ; obo:BFO_0000132 ?trajectoryHalf ;
            obo:BFO_0000199 ?trajectoryInterval .
        ?trajectoryHalf a base:HalfInning .
        ?trajectoryInterval a obo:BFO_0000038 .
        ?plateAppearance obo:BFO_0000132 ?trajectoryHalf .
        FILTER(REGEX(STR(?trajectory), "^https://baseballontology[.]org/data/game/[0-9]+/runner-trajectory/[^/]+$"))
      }
    }
    OPTIONAL {
      ?originDesignation a base:BaserunningSegmentOriginDesignation ;
          cco:ont00001808 ?act ; cco:ont00001916 ?originBase .
        ?originBase a base:Base .
      OPTIONAL {
        ?originDesignation obo:BFO_0000176 ?originRecord .
        ?originRecord a base:BaseballEventRecord .
      }
      OPTIONAL {
        ?originIdentifier a cco:ont00000649 ; cco:ont00001916 ?originBase ;
            cco:ont00001765 ?originCode .
      }
    }
    OPTIONAL {
      ?resolution a base:SafeProcess ; obo:BFO_0000117 ?safeJudgment .
      ?safeJudgment a base:SafeJudgmentAct ; cco:ont00001986 ?safeDecision .
      ?safeDecision a base:SafeDecisionICE ; cco:ont00001808 ?resolution, ?destinationBase .
      ?destinationBase a base:Base .
      OPTIONAL {
        ?destinationIdentifier a cco:ont00000649 ;
            cco:ont00001916 ?destinationBase ; cco:ont00001765 ?destinationCode .
      }
    }
    OPTIONAL {
      ?contactPlay a base:BattedBallPlayProcess ;
          obo:BFO_0000132 ?plateAppearance ; obo:BFO_0000117 ?resolution .
    }
    OPTIONAL {
      ?award obo:BFO_0000132 ?plateAppearance ; cco:ont00001803 ?act .
        { ?award a base:WalkProcess } UNION { ?award a base:HitByPitchProcess }
        ?awardRule a base:BaseballRule ; cco:ont00001974 ?act .
        ?awardEpisode a base:RunnerResolutionEpisode ; obo:BFO_0000117 ?act, ?resolution .
        { ?resolution a base:SafeProcess } UNION { ?resolution a base:RunProcess }
    }
    OPTIONAL {
      ?record a base:BaseballEventRecord ; cco:ont00001808 ?resolution, ?act .
    }
    OPTIONAL {
      ?batterAct a base:BatterAct ; obo:BFO_0000132 ?plateAppearance ; obo:BFO_0000055 ?batterRole .
      ?batterRole a base:BatterRole ; obo:BFO_0000197 ?batter .
    }
    # HOME=0 is an analytical initial position, never an RDF origin assertion.
    BIND(IF(?originCode = "1B", 1, IF(?originCode = "2B", 2, IF(?originCode = "3B", 3, 1/0))) AS ?segmentOriginPosition)
    BIND(IF(BOUND(?batter) && ?runner = ?batter, 0, ?segmentOriginPosition) AS ?metricOrigin)
    BIND(EXISTS { ?resolution a base:SafeProcess } AS ?hasSafeType)
    BIND(EXISTS { ?resolution a base:OutProcess } AS ?hasOutType)
    BIND(EXISTS { ?resolution a base:RunProcess } AS ?hasRunType)
  }
  FILTER(STRSTARTS(STR(?graph), "https://w3id.org/baseball/graph/game/"))
}
ORDER BY ?game ?plateAppearance ?resolution ?act

} BIND("runner_movement" AS ?kind) BIND(?resolution AS ?entity) }
}
